function calc(items=state.cart,discount=state.discount){const metal=round(items.reduce((a,i)=>a+i.weight*i.rate*i.qty,0));const making=round(items.reduce((a,i)=>a+i.weight*i.making*i.qty,0));const gross=round(metal+making);const dis=round(gross*Number(discount)/100);const taxable=round(gross-dis);const cgst=round(taxable*.015),sgst=cgst;const withTax=round(taxable+cgst+sgst);const total=Math.round(withTax);return {metal,making,gross,discount:dis,taxable,cgst,sgst,withTax,total,roundoff:round(total-withTax)};}
invoices.forEach(i=>{i.shop={...shop};i.paid=Math.min(i.paid,calc(i.items,i.discount).total)});
function customer(id){return customers.find(c=>c.id===id)||customers[0];}function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">Main branch / Counter 01</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function button(label,action,primary=false,ico=''){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${ico?icon(ico):''}${label}</button>`;}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),3200);}
function rates(){return `<div class="rate-strip"><span class="rate-label">TODAY'S METAL RATES</span><span class="metal-rate"><span class="metal-type">22K GOLD</span><strong>${money(products.find(p=>p.purity.startsWith('22K')).rate)} / g</strong></span><span class="metal-rate"><span class="metal-type">18K GOLD</span><strong>${money(products.find(p=>p.purity.startsWith('18K')).rate)} / g</strong></span><span class="metal-rate"><span class="metal-type silver">SILVER</span><strong>${money(products.find(p=>p.metal==='Silver').rate)} / g</strong></span><span class="right">Illustrative rates · 04 Oct 2026</span></div>`;}
function shell(){document.querySelector('#sidebar').innerHTML=`<a class="brand" href="#dashboard"><div><strong><span>Kailash Nath</span><span>Pradhan</span></strong><small>JEWELLERS</small></div></a><div class="nav-label">WORKSPACE</div>${nav.map((n,i)=>`${i===7?'<div class="nav-label">ADMINISTRATION</div>':''}<a href="#${n[0]}" class="navlink ${state.page===n[0]?'active':''}">${icon(n[2])}${n[1]}${n[0]==='invoices'?'<span class="count">'+invoices.length+'</span>':''}</a>`).join('')}<div class="side-bottom"><strong>${esc(shop.name)}</strong><span>Main branch · Jaunpur</span><div style="margin-top:14px">Interactive demo<br><span>Sample data · no real transactions</span></div></div>`;document.querySelector('#topbar').innerHTML=`<div class="flex"><button class="mobile-toggle" aria-label="Toggle navigation" onclick="document.body.classList.toggle('menu-open')">☰</button><span class="crumb">Workspace / <strong>${nav.find(n=>n[0]===state.page)?.[1]||'Invoice detail'}</strong></span></div><div class="topright"><span class="demo-badge">CLIENT PREVIEW</span><span class="muted" style="font-size:12px">04 Oct 2026</span><span class="avatar">MP</span><div class="profile">Mimmo Patel<small>Owner · Demo role</small></div></div>`;}
function invoiceRows(arr){return arr.length?arr.map(i=>{let c=customer(i.customerId),n=calc(i.items,i.discount),due=Math.max(0,n.total-i.paid);return `<tr><td><button class="linkbtn" onclick="openInvoice('${i.id}')">${i.id}</button><small>${i.date} · ${i.time}</small></td><td>${esc(c.name)}<small>${c.phone}</small></td><td>${i.items.map(x=>esc(x.name)).join(', ')}</td><td class="numcell">${money(n.total)}</td><td><span class="tag ${i.status==='Cancelled'?'red':i.status==='Draft'?'blue':due?'amber':''}">${i.status==='Cancelled'?'Cancelled':i.status==='Draft'?'Draft':due?'Partial':'Paid'}</span></td><td>${i.method}</td><td><button class="linkbtn" onclick="openInvoice('${i.id}')">View</button></td></tr>`}).join(''):'<tr><td colspan="7" class="empty">No invoices match this selection.</td></tr>';}
function dashboard(){let today=invoices.filter(i=>i.date==='2026-10-04'&&i.status==='Finalized'),sales=today.reduce((a,i)=>a+calc(i.items,i.discount).total,0),col=today.reduce((a,i)=>a+i.paid,0),due=invoices.filter(i=>i.status==='Finalized').reduce((a,i)=>a+calc(i.items,i.discount).total-i.paid,0);return heading('Shop overview','A clear view of your counter, collections and stock.',button('New bill',"go('billing')",true,'plus'))+rates()+`<div class="metrics"><div class="metric"><div class="cap">Today's sales ${icon('report')}</div><div class="num">${money(sales)}</div><div class="foot"><em>${today.length} invoices</em> finalized today</div></div><div class="metric"><div class="cap">Amount collected ${icon('wallet')}</div><div class="num">${money(col)}</div><div class="foot">Cash + UPI + other payments</div></div><div class="metric"><div class="cap">Outstanding dues ${icon('people')}</div><div class="num">${money(due)}</div><div class="foot">Across finalized demo invoices</div></div><div class="metric"><div class="cap">Available stock ${icon('stock')}</div><div class="num">${products.reduce((a,x)=>a+x.qty,0)} <span style="font-size:16px;font-weight:400">pieces / pairs</span></div><div class="foot">${products.length} stock tags across gold & silver</div></div></div><div class="grid-two"><div class="panel"><div class="panel-head"><h2>Sales this week</h2><span class="muted" style="font-size:12px">28 Sep – 04 Oct · Illustration</span></div><div class="chart-box"><div class="chart-meta"><span>Daily sales pattern</span><span class="muted">Gold & silver jewellery</span></div><div class="chart">${[48,76,55,86,65,90,62].map((h,i)=>`<div class="barcol"><div class="bar ${i===6?'today':''}" style="height:${h}%" title="Illustrative sales bar"></div><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}</div></div></div><div class="panel"><div class="panel-head"><h2>Collections today</h2><button class="linkbtn" onclick="go('payments')">View ledger</button></div><div class="panel-body">${['Cash','UPI','Card','Bank'].map(m=>{let v=today.reduce((a,i)=>a+collectionByMethod(i,m),0);return `<div class="progress-row"><div class="progress-title"><span>${m}</span><strong>${money(v)}</strong></div><div class="track"><div class="fill" style="width:${col?v/col*100:0}%"></div></div></div>`}).join('')}<div class="notice blue" style="margin-bottom:0">Need a walkthrough? Explore a bill from item selection to invoice print.</div><button class="linkbtn" style="margin-top:10px" onclick="go('guide')">Open demo walkthrough</button></div></div></div><div class="panel"><div class="panel-head"><h2>Recent invoices</h2><button class="linkbtn" onclick="go('invoices')">View all invoices</button></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Items</th><th class="numcell">Total</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody>${invoiceRows(invoices.slice(0,4))}</tbody></table></div></div><div class="footer-note">Client review prototype · Demo changes last for this browser session · Production scope subject to approval</div>`;}
function go(page){location.hash=page;render();}function render(){state.page=(location.hash.slice(1)||'dashboard').split('/')[0];shell();document.body.classList.remove('menu-open');const pages={dashboard,billing,invoices:invoicePage,inventory,customers:customerPage,payments,reports,settings,guide,invoice:invoiceDetail};document.querySelector('#content').innerHTML=(pages[state.page]||dashboard)();}
function modal(title,body,footer=''){document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;const d=document.querySelector('#modal');if(!d.open)d.showModal();}
function closeModal(){document.querySelector('#modal').close();}
function error(t){const el=document.querySelector('#form-error');if(el)el.textContent=t;else toast(t);return false;}
function startNewBill(){state.cart=[];state.discount=0;state.paid=0;state.customerId='c1';state.editingInvoice=null;state.notes='';state.paymentMethod='Cash';go('billing');}
function billing(){let n=calc(),c=customer(state.customerId);return heading('Create a new bill','Customer details, jewellery items and payment in one workspace.',button('Invoice history',"go('invoices')"))+`<div class="step-strip"><span class="active"><b>1</b>Customer & items</span><span class="${state.cart.length?'active':''}"><b>2</b>Review & payment</span><span><b>3</b>Finalize & print</span></div><div class="billing-layout"><div class="billing-left"><div class="panel"><div class="panel-head"><h2>Customer & invoice details</h2><button class="linkbtn" onclick="customerModal()">+ New customer</button></div><div class="panel-body"><div class="form-grid"><div class="field"><label for="billcustomer">Customer</label><select id="billcustomer" onchange="state.customerId=this.value;render()">${customers.map(c=>`<option value="${c.id}" ${c.id===state.customerId?'selected':''}>${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}</select><span class="hint">${esc(c.city)}, ${esc(c.state)} · State code ${esc(c.code)}</span></div><div class="field"><label>Invoice number</label><input value="${state.editingInvoice||'Assigned on finalization'}" readonly><span class="hint">04 October 2026 · Counter 01</span></div></div></div></div><div class="panel spaced"><div class="panel-head"><h2>Jewellery items <span class="muted" style="font-weight:400">(${state.cart.length})</span></h2><button class="btn small" onclick="itemModal()">${icon('plus')}Add item</button></div><div class="table-wrap"><table class="cart-table"><thead><tr><th>Item / purity</th><th>Qty</th><th>Net wt (g)</th><th>Rate / g</th><th>Making / g</th><th>Value</th><th></th></tr></thead><tbody>${state.cart.length?state.cart.map((i,k)=>`<tr><td class="item-name"><strong>${esc(i.name)}</strong><small>${esc(i.tag)} · ${esc(i.purity)}</small></td><td><input aria-label="Quantity for ${esc(i.name)}" class="cellinput" style="width:55px" type="number" min="1" max="${products.find(p=>p.id===i.id)?.qty||1}" step="1" value="${i.qty}" onchange="updateItem(${k},'qty',this.value)"></td><td><input aria-label="Net weight for ${esc(i.name)}" class="cellinput" type="number" min="0.001" step="0.001" value="${i.weight.toFixed(3)}" onchange="updateItem(${k},'weight',this.value)"></td><td><input aria-label="Rate for ${esc(i.name)}" class="cellinput" type="number" min="0.01" step="0.01" value="${i.rate}" onchange="updateItem(${k},'rate',this.value)"></td><td><input aria-label="Making charge for ${esc(i.name)}" class="cellinput" type="number" min="0" step="0.01" value="${i.making}" onchange="updateItem(${k},'making',this.value)"></td><td class="numcell">${money(i.weight*(i.rate+i.making)*i.qty)}</td><td><button class="remove" aria-label="Remove ${esc(i.name)}" onclick="state.cart.splice(${k},1);render()">×</button></td></tr>`).join(''):`<tr><td colspan="7"><div class="empty"><h3>No items added yet</h3><p>Select a tagged jewellery item from your inventory.</p><button class="btn primary" style="margin-top:15px" onclick="itemModal()">Add your first item</button><div class="inline-note"><button class="linkbtn" onclick="loadSample()">Try the silver payal sample bill</button></div></div></td></tr>`}</tbody></table></div><div class="row-actions"><span class="muted" style="font-size:12px">Net weight excludes stones / other weight. Making charge uses a per-gram basis in this demo.</span></div></div><div class="panel spaced"><div class="panel-head"><h2>Discount & notes</h2><span class="tag blue">Demo owner access</span></div><div class="panel-body"><div class="form-grid"><div class="field"><label for="discount">Discount (%) on metal + making</label><input id="discount" type="number" min="0" max="100" value="${state.discount}" onchange="updateDiscount(this.value)"><span class="hint">Final software: discount permissions and approval limits.</span></div><div class="field"><label for="billnotes">Notes (optional)</label><input id="billnotes" placeholder="e.g. customer delivery note" value="${esc(state.notes)}" onchange="state.notes=this.value"></div></div></div></div><div class="notice">Sample calculation: 3% GST for an intra-state jewellery sale. HSN, purity and tax rules require client/accountant confirmation.</div></div><aside class="panel bill-summary"><div class="panel-head"><h2>Bill summary</h2><span class="tag blue">Draft</span></div><div class="panel-body"><div class="summary-row"><span>Metal value</span><strong>${money(n.metal)}</strong></div><div class="summary-row"><span>Making charges</span><strong>${money(n.making)}</strong></div><div class="summary-row"><span>Discount (${state.discount}%)</span><strong>−${money(n.discount)}</strong></div><div class="summary-row"><span>Taxable value</span><strong>${money(n.taxable)}</strong></div><div class="summary-row"><span>CGST 1.5%</span><strong>${money(n.cgst)}</strong></div><div class="summary-row"><span>SGST 1.5%</span><strong>${money(n.sgst)}</strong></div><div class="summary-row"><span>Round off</span><strong>${n.roundoff>=0?'+':''}${money(n.roundoff)}</strong></div><div class="summary-row total"><span>Total payable</span><span>${money(n.total)}</span></div><h3 style="margin-top:13px">Payment</h3><div class="payment-choice">${['Cash','UPI','Card','Bank'].map(m=>`<button class="${state.paymentMethod===m?'active':''}" onclick="state.paymentMethod='${m}';render()">${m}</button>`).join('')}</div><div class="field"><label for="paid">Amount received (₹)</label><input id="paid" type="number" min="0" max="${n.total}" value="${state.paid}" onchange="updatePaid(this.value)"></div><button class="linkbtn" style="margin-top:5px" onclick="state.paid=calc().total;render()">Mark fully paid</button><div class="summary-row ${n.total-state.paid>0?'due':''}"><span>Balance due</span><strong>${money(Math.max(0,n.total-state.paid))}</strong></div><button class="btn primary" ${state.cart.length?'':'disabled'} onclick="reviewBill()">Review & finalize</button><button class="btn" ${state.cart.length?'':'disabled'} onclick="saveDraft()">Save draft</button><p class="inline-note">Finalization saves the invoice, payment and stock movement together in this demo.</p></div></aside></div>`;}
function loadSample(){const p=products.find(p=>p.id==='p2');if(p.qty<1)return toast('Silver payal is sold out. Add stock or reset the demo.');state.cart=[{...p,qty:1}];state.discount=40;state.paid=calc().total;render();toast('Sample bill loaded. Review the amounts and payment.');}
function itemModal(){modal('Add jewellery item',`<div class="item-picker">${products.map(p=>`<div class="item-pick"><div><strong>${esc(p.name)}</strong><small>${esc(p.tag)} · ${esc(p.purity)} · ${p.weight.toFixed(3)} g<br>${money(p.rate)} / g · ${p.qty} available</small></div><button class="btn small" ${p.qty<1?'disabled':''} onclick="addItem('${p.id}')">${p.qty<1?'Sold out':'Add item'}</button></div>`).join('')}</div><p class="inline-note">Gold rate matches the listed purity. No second purity multiplier applies.</p>`);}
function addItem(id){const p=products.find(p=>p.id===id),exists=state.cart.find(i=>i.id===id);if(exists)return toast('This tag is already in the bill. Edit its quantity in the item row.');if(!p||p.qty<1)return toast('Item is out of stock.');state.cart.push({...p,qty:1});state.paid=0;closeModal();render();toast(p.name+' added to bill.');}
function updateItem(k,field,v){const num=Number(v),p=products.find(p=>p.id===state.cart[k].id);if(!Number.isFinite(num)||num<0||(field!=='making'&&num===0)||field==='qty'&&(!Number.isInteger(num)||num>p.qty)){render();return toast('Enter a valid value. Quantity must match available stock.');}state.cart[k][field]=num;state.paid=Math.min(state.paid,calc().total);render();}
function updateDiscount(v){const n=Number(v);if(!Number.isFinite(n)||n<0||n>100){render();return toast('Discount must be between 0% and 100%.');}state.discount=n;state.paid=Math.min(state.paid,calc().total);render();}
function updatePaid(v){const n=Number(v);if(!Number.isFinite(n)||n<0||n>calc().total){render();return toast('Payment must be between zero and the bill total.');}state.paid=round(n);render();}
function validBill(){if(!state.cart.length)return error('Add at least one item.');if(state.paid>calc().total||state.paid<0)return error('Review the payment amount.');for(const i of state.cart){const p=products.find(p=>p.id===i.id);if(!p||i.qty>p.qty)return error(i.name+' does not have enough stock.');}return true;}
function reviewBill(){if(!validBill())return;let n=calc();modal('Review before finalization',`<div class="notice blue" style="margin-top:0">Finalized bills preserve their item rates and calculations. Stock will reduce when you confirm.</div><div class="summary-row"><span>Customer</span><strong>${esc(customer(state.customerId).name)}</strong></div><div class="summary-row"><span>Jewellery items</span><strong>${state.cart.length}</strong></div><div class="summary-row"><span>Payment method</span><strong>${state.paymentMethod}</strong></div><div class="summary-row total"><span>Total</span><strong>${money(n.total)}</strong></div><div class="summary-row"><span>Received</span><strong>${money(state.paid)}</strong></div><div class="summary-row due"><span>Balance due</span><strong>${money(n.total-state.paid)}</strong></div><p class="inline-note">Demo transaction only. No payment is charged.</p>`,button('Back to edit','closeModal()')+button('Confirm & create invoice','finalizeBill()',true));}
function snapshotBill(status){return {id:state.editingInvoice||shop.invoicePrefix+'-'+String(++nextInvoiceNumber),customerId:state.customerId,date:'2026-10-04',items:state.cart.map(i=>({...i})),discount:state.discount,paid:status==='Draft'?0:state.paid,method:state.paymentMethod,status,time:'Demo session',notes:state.notes,shop:{...shop}};}
let nextInvoiceNumber=1124;
function saveDraft(){if(!validBill())return;const i=snapshotBill('Draft');const at=invoices.findIndex(x=>x.id===i.id);if(at>=0)invoices[at]=i;else invoices.unshift(i);state.editingInvoice=i.id;toast('Draft saved. Stock and collections are unchanged.');go('invoices');}
function finalizeBill(){if(!validBill())return;let i=snapshotBill('Finalized');state.cart.forEach(x=>products.find(p=>p.id===x.id).qty-=x.qty);const at=invoices.findIndex(x=>x.id===i.id);if(at>=0)invoices[at]=i;else invoices.unshift(i);events.unshift({time:'Now',action:'Invoice '+i.id+' finalized',detail:'Mimmo Patel · Stock reduced · '+i.method+' '+money(i.paid)});state.cart=[];state.editingInvoice=null;closeModal();openInvoice(i.id);toast('Invoice saved. Stock and payment records updated.');}
function resumeDraft(id){let i=invoices.find(x=>x.id===id);if(!i||i.status!=='Draft')return;state.cart=i.items.map(x=>({...x}));state.customerId=i.customerId;state.discount=i.discount;state.paid=0;state.paymentMethod=i.method;state.notes=i.notes||'';state.editingInvoice=id;go('billing');}
function invoicePage(){const arr=invoices.filter(i=>{const n=calc(i.items,i.discount),due=n.total-i.paid;return (state.invoiceFilter==='All'||state.invoiceFilter==='Draft'&&i.status==='Draft'||state.invoiceFilter==='Paid'&&i.status==='Finalized'&&due===0||state.invoiceFilter==='Partial'&&i.status==='Finalized'&&due>0||state.invoiceFilter==='Cancelled'&&i.status==='Cancelled')&&(i.id+' '+customer(i.customerId).name).toLowerCase().includes(state.invoiceQuery.toLowerCase());});return heading('Invoices','Find, reprint or continue a saved draft.',button('New bill','startNewBill()',true,'plus'))+`<div class="panel"><div class="tabs">${['All','Paid','Partial','Draft','Cancelled'].map(x=>`<button class="tab ${state.invoiceFilter===x?'active':''}" onclick="state.invoiceFilter='${x}';render()">${x}</button>`).join('')}</div><div class="toolbar"><input class="searchbox" aria-label="Search invoices" placeholder="Search invoice number or customer" value="${esc(state.invoiceQuery)}" oninput="state.invoiceQuery=this.value;refreshInvoiceRows()"><span class="right muted" style="font-size:12px" id="invoice-count">${arr.length} invoices</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Items</th><th class="numcell">Total</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody id="invoice-rows">${invoiceRows(arr)}</tbody></table></div></div><div class="notice blue">Reprinting uses the saved invoice details. Changing today's metal rates will not change a finalized invoice.</div>`;}
function refreshInvoiceRows(){const q=state.invoiceQuery.toLowerCase(),arr=invoices.filter(i=>{let due=calc(i.items,i.discount).total-i.paid;return (i.id+' '+customer(i.customerId).name).toLowerCase().includes(q)&&(state.invoiceFilter==='All'||state.invoiceFilter==='Draft'&&i.status==='Draft'||state.invoiceFilter==='Paid'&&i.status==='Finalized'&&!due||state.invoiceFilter==='Partial'&&i.status==='Finalized'&&due>0||state.invoiceFilter==='Cancelled'&&i.status==='Cancelled');});document.querySelector('#invoice-rows').innerHTML=invoiceRows(arr);document.querySelector('#invoice-count').textContent=arr.length+' invoices';}
function openInvoice(id){location.hash='invoice/'+id;state.page='invoice';render();}
function amountWords(n){const one=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],ten=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];function w(v){if(v<20)return one[v];if(v<100)return ten[Math.floor(v/10)]+(v%10?' '+one[v%10]:'');if(v<1000)return one[Math.floor(v/100)]+' Hundred'+(v%100?' '+w(v%100):'');if(v<100000)return w(Math.floor(v/1000))+' Thousand'+(v%1000?' '+w(v%1000):'');if(v<10000000)return w(Math.floor(v/100000))+' Lakh'+(v%100000?' '+w(v%100000):'');return w(Math.floor(v/10000000))+' Crore'+(v%10000000?' '+w(v%10000000):'');}return 'Rupees '+(n?w(Math.floor(n)):'Zero')+' Only';}
function invoiceMarkup(i){const n=calc(i.items,i.discount),c=customer(i.customerId),s=i.shop||shop;return `<article class="invoice-sheet"><div class="invoice-top"><div><div class="invoice-brand">${esc(s.name)}</div><p>${esc(s.address)}<br>Phone: ${esc(s.phone)}<br>GSTIN: ${esc(s.gstin)}</p></div><div class="invoice-title">${i.status==='Draft'?'DRAFT ESTIMATE':i.status==='Cancelled'?'CANCELLED INVOICE':'TAX INVOICE'}<p>CLIENT DEMO / SAMPLE<br>${esc(i.id)}<br>${i.date}</p></div></div><div class="invoice-meta"><div><span class="label muted">BILL TO</span><br><strong>${esc(c.name)}</strong><p>${esc(c.city)}, ${esc(c.state)}<br>Phone: ${esc(c.phone)}<br>State code: ${esc(c.code)} · Unregistered consumer</p></div><div><span class="muted">PLACE OF SUPPLY</span><br>${esc(c.state)} (${esc(c.code)})<p>Counter 01 · Main branch<br>Payment: ${esc(i.method)}<br>${i.status==='Cancelled'?'Cancelled · amounts reversed in demo':'Status: '+i.status}</p></div></div><div class="table-wrap"><table><thead><tr><th>Item / HSN</th><th>Purity</th><th>Qty</th><th class="numcell">Net wt / unit</th><th class="numcell">Rate / g</th><th class="numcell">Making</th><th class="numcell">Value</th></tr></thead><tbody>${i.items.map(x=>`<tr><td>${esc(x.name)}<small>${esc(x.tag)} · HSN ${esc(x.hsn)}*</small></td><td>${esc(x.purity)}</td><td>${x.qty}</td><td class="numcell">${x.weight.toFixed(3)} g</td><td class="numcell">${money(x.rate)}</td><td class="numcell">${money(x.weight*x.making*x.qty)}</td><td class="numcell">${money(x.weight*(x.rate+x.making)*x.qty)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-totals"><div class="summary-row"><span>Metal value</span><strong>${money(n.metal)}</strong></div><div class="summary-row"><span>Making charges</span><strong>${money(n.making)}</strong></div><div class="summary-row"><span>Discount (${i.discount}%)</span><strong>−${money(n.discount)}</strong></div><div class="summary-row"><span>Taxable value</span><strong>${money(n.taxable)}</strong></div><div class="summary-row"><span>CGST 1.5%</span><strong>${money(n.cgst)}</strong></div><div class="summary-row"><span>SGST 1.5%</span><strong>${money(n.sgst)}</strong></div><div class="summary-row"><span>Round off</span><strong>${n.roundoff>=0?'+':''}${money(n.roundoff)}</strong></div><div class="summary-row total"><span>Grand total</span><strong>${money(n.total)}</strong></div><div class="summary-row"><span>Paid</span><strong>${money(i.paid)}</strong></div><div class="summary-row"><span>Balance due</span><strong>${money(i.status==='Cancelled'?0:n.total-i.paid)}</strong></div></div><p><strong>Amount in words: ${amountWords(n.total)}</strong><br>${i.notes?'Note: '+esc(i.notes)+'<br>':''}</p><div class="invoice-bottom"><div><strong>Bank & terms</strong><p>${esc(s.bank)}<br>${esc(s.terms)}</p></div><div style="text-align:right">For ${esc(s.name)}<br><br><br>Authorised signatory</div></div><p style="margin-top:23px;font-size:10px">DEMO ONLY · No real transaction. *HSN, purity, business details and applicable tax treatment require confirmation before production use.</p></article>`;}
function invoiceDetail(){const id=location.hash.split('/')[1],i=invoices.find(x=>x.id===id);if(!i)return heading('Invoice not found','Go back to invoice history.',button('View invoices',"go('invoices')"));return heading(i.status==='Draft'?'Saved draft':i.status==='Cancelled'?'Cancelled invoice':'Invoice saved',i.status==='Draft'?'Continue editing before finalization.':i.status==='Cancelled'?'Original document remains available with its cancellation history.':'Review the saved document, collect dues or print a copy.',`<div class="flex wrap">${button('All invoices',"go('invoices')")}${i.status==='Draft'?button('Continue draft',`resumeDraft('${i.id}')`,true):button('Print / PDF',`printInvoice('${i.id}')`,true,'print')}</div>`)+`${i.status==='Finalized'?`<div class="notice blue" style="margin-top:0;display:flex;justify-content:space-between;align-items:center;gap:10px"><span>Finalized invoice · stock movement recorded · payment: ${money(i.paid)}</span><div class="flex">${calc(i.items,i.discount).total>i.paid?`<button class="linkbtn" onclick="receiptModal('${i.id}')">Collect due</button>`:''}<button class="linkbtn" style="color:var(--red)" onclick="cancelModal('${i.id}')">Cancel demo invoice</button></div></div>`:''}`+invoiceMarkup(i);}
function printInvoice(id){const i=invoices.find(x=>x.id===id);if(!i)return;document.querySelector('#print-area').innerHTML=invoiceMarkup(i);window.print();events.unshift({time:'Now',action:'Print preview opened: '+id,detail:'Saved invoice snapshot · no new transaction'});}
function cancelModal(id){modal('Cancel demo invoice',`<div class="notice">Production cancellation / credit-note rules will follow the approved accounting workflow.</div><p>This demo will restore the sold quantities and remove the invoice from sales and dues. The original document stays in the invoice history.</p><div class="field spaced"><label for="cancel-reason">Reason</label><input id="cancel-reason" placeholder="Enter a cancellation reason" required></div><div id="form-error" class="error spaced"></div>`,button('Keep invoice','closeModal()')+button('Confirm cancellation',`cancelInvoice('${id}')`));}
function cancelInvoice(id){const reason=document.querySelector('#cancel-reason').value.trim();if(!reason)return error('Enter a reason to continue.');const i=invoices.find(x=>x.id===id);if(i.status!=='Finalized')return error('This invoice is no longer finalized.');i.items.forEach(x=>{const p=products.find(p=>p.id===x.id);if(p)p.qty+=x.qty;});i.status='Cancelled';i.cancellationReason=reason;events.unshift({time:'Now',action:'Invoice '+id+' cancelled',detail:reason+' · '+money(i.paid)+' payment marked for refund (demo)'});closeModal();render();toast('Cancelled. Stock restored; payment marked for refund in the demo.');}
function inventory(){const arr=products.filter(p=>(state.inventoryFilter==='All'||p.metal===state.inventoryFilter)&&(p.name+' '+p.tag).toLowerCase().includes(state.inventoryQuery.toLowerCase()));return heading('Jewellery inventory','Track tagged pieces, weights and available stock.',button('Add stock',"stockModal()",true,'plus'))+`<div class="statline"><div><small>Gold weight available</small><strong>${products.filter(p=>p.metal==='Gold').reduce((a,p)=>a+p.weight*p.qty,0).toFixed(3)} g</strong></div><div><small>Silver weight available</small><strong>${products.filter(p=>p.metal==='Silver').reduce((a,p)=>a+p.weight*p.qty,0).toFixed(3)} g</strong></div><div><small>Available units</small><strong>${products.reduce((a,p)=>a+p.qty,0)}</strong></div><div><small>Sold-out tags</small><strong>${products.filter(p=>!p.qty).length}</strong></div></div><div class="panel"><div class="tabs">${['All','Gold','Silver'].map(m=>`<button class="tab ${state.inventoryFilter===m?'active':''}" onclick="state.inventoryFilter='${m}';render()">${m}</button>`).join('')}</div><div class="toolbar"><input class="searchbox" placeholder="Search item name or stock tag" aria-label="Search inventory" value="${esc(state.inventoryQuery)}" oninput="state.inventoryQuery=this.value;refreshInventoryRows()"><button class="btn small right" onclick="exportCSV('stock')">Export stock</button></div><div class="table-wrap"><table><thead><tr><th>Item / stock tag</th><th>Metal / purity</th><th class="numcell">Net wt / unit</th><th class="numcell">Rate / g</th><th>Location</th><th>Available</th><th></th></tr></thead><tbody id="inventory-rows">${inventoryRows(arr)}</tbody></table></div></div><div class="notice blue">Demo items use tagged stock. Bulk silver stock, stone details, HUID and weighing-scale integration can be scoped separately.</div>`;}
function inventoryRows(arr){return arr.length?arr.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.tag)}</small></td><td>${p.metal}<small>${p.purity}</small></td><td class="numcell">${p.weight.toFixed(3)} g</td><td class="numcell">${money(p.rate)}</td><td>${esc(p.location)}</td><td><span class="tag ${p.qty?'':'red'}">${p.qty} ${p.qty?'available':'sold out'}</span></td><td><button class="linkbtn" onclick="stockDetail('${p.id}')">Details</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No stock matches this search.</td></tr>';}
function refreshInventoryRows(){document.querySelector('#inventory-rows').innerHTML=inventoryRows(products.filter(p=>(state.inventoryFilter==='All'||p.metal===state.inventoryFilter)&&(p.name+' '+p.tag).toLowerCase().includes(state.inventoryQuery.toLowerCase())));}
function stockDetail(id){const p=products.find(x=>x.id===id);modal(esc(p.name),`<div class="summary-row"><span>Stock tag</span><strong>${esc(p.tag)}</strong></div><div class="summary-row"><span>Metal & purity</span><strong>${p.metal} · ${p.purity}</strong></div><div class="summary-row"><span>Net weight / unit</span><strong>${p.weight.toFixed(3)} g</strong></div><div class="summary-row"><span>Making charge basis</span><strong>${money(p.making)} / g</strong></div><div class="summary-row"><span>Available stock</span><strong>${p.qty} units</strong></div><h3 class="spaced">Invoice movements</h3>${invoices.filter(i=>i.items.some(x=>x.id===id)).map(i=>`<div class="list-row" style="padding-left:0;padding-right:0"><div>${i.id}<small>${i.status} · ${customer(i.customerId).name}</small></div><button class="linkbtn" onclick="closeModal();openInvoice('${i.id}')">View</button></div>`).join('')||'<p class="muted">No invoice movements for this tag.</p>'}`,button('Close','closeModal()'));}
function stockModal(){modal('Add stock to an existing tag',`<div class="form-grid"><div class="field full"><label for="stock-item">Jewellery item</label><select id="stock-item">${products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.tag)}</option>`).join('')}</select></div><div class="field"><label for="stock-qty">Units received</label><input id="stock-qty" type="number" min="1" step="1" value="1"></div><div class="field"><label for="stock-ref">Purchase / adjustment reference</label><input id="stock-ref" placeholder="e.g. opening stock correction"></div></div><div class="notice blue">Adds units with the tag's existing weight and rate. A separate purchase module can be added after discovery.</div><div id="form-error" class="error"></div>`,button('Cancel','closeModal()')+button('Record stock receipt','addStock()',true));}
function addStock(){const id=document.querySelector('#stock-item').value,qty=Number(document.querySelector('#stock-qty').value),ref=document.querySelector('#stock-ref').value.trim();if(!Number.isInteger(qty)||qty<1||qty>10000)return error('Enter a whole quantity from 1 to 10,000.');if(!ref)return error('Add a reference for the stock entry.');products.find(p=>p.id===id).qty+=qty;events.unshift({time:'Now',action:'Stock received: '+products.find(p=>p.id===id).tag,detail:qty+' units · '+ref});closeModal();render();toast('Stock receipt recorded. Available stock updated.');}
function outstanding(id){return invoices.filter(i=>i.customerId===id&&i.status==='Finalized').reduce((a,i)=>a+calc(i.items,i.discount).total-i.paid,0);}
function customerPage(){let arr=customers.filter(c=>(c.name+' '+c.phone+' '+c.city).toLowerCase().includes(state.customerFilter.toLowerCase()));return heading('Customers','Customer details, purchase history and outstanding balances.',button('New customer','customerModal()',true,'plus'))+`<div class="panel"><div class="toolbar"><input class="searchbox" placeholder="Search name, phone or city" aria-label="Search customers" value="${esc(state.customerFilter)}" oninput="state.customerFilter=this.value;refreshCustomerRows()"><span class="muted right" style="font-size:12px">${customers.length} customers</span></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Mobile number</th><th>City</th><th>Invoices</th><th class="numcell">Outstanding</th><th></th></tr></thead><tbody id="customer-rows">${customerRows(arr)}</tbody></table></div></div>`;}
function customerRows(arr){return arr.length?arr.map(c=>`<tr><td><div class="flex"><span class="avatar">${esc(c.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><strong>${esc(c.name)}</strong></div></td><td>${esc(c.phone)}</td><td>${esc(c.city)}</td><td>${invoices.filter(i=>i.customerId===c.id&&i.status==='Finalized').length}</td><td class="numcell" style="color:${outstanding(c.id)?'var(--red)':'var(--ink)'}">${money(outstanding(c.id))}</td><td><button class="linkbtn" onclick="customerDetail('${c.id}')">View ledger</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No customers match this search.</td></tr>';}
function refreshCustomerRows(){document.querySelector('#customer-rows').innerHTML=customerRows(customers.filter(c=>(c.name+' '+c.phone+' '+c.city).toLowerCase().includes(state.customerFilter.toLowerCase())));}
function customerModal(){modal('Add a customer',`<div class="form-grid"><div class="field"><label for="cname">Full name *</label><input id="cname" autocomplete="off" placeholder="Customer name"></div><div class="field"><label for="cphone">Mobile number *</label><input id="cphone" inputmode="tel" placeholder="10-digit mobile number" maxlength="10"></div><div class="field"><label for="ccity">City *</label><input id="ccity" value="Jaunpur"></div><div class="field"><label>State</label><input value="Uttar Pradesh (09)" readonly><span class="hint">This demo models intra-state sales.</span></div></div><div id="form-error" class="error spaced"></div>`,button('Cancel','closeModal()')+button('Save customer','saveCustomer()',true));}
function saveCustomer(){let name=document.querySelector('#cname').value.trim(),phone=document.querySelector('#cphone').value.trim(),city=document.querySelector('#ccity').value.trim();if(!name||!city)return error('Customer name and city are required.');if(!/^[6-9]\d{9}$/.test(phone))return error('Enter a valid 10-digit mobile number.');if(customers.some(c=>c.phone.replace(/\s/g,'')===phone))return error('This mobile number already exists.');const c={id:'c'+(customers.length+1),name,phone,city,state:'Uttar Pradesh',code:'09'};customers.push(c);if(state.page==='billing')state.customerId=c.id;closeModal();render();toast('Customer saved'+(state.page==='billing'?' and selected for this bill.':'.'));}
function customerDetail(id){const c=customer(id),arr=invoices.filter(i=>i.customerId===id);modal('Customer ledger',`<div class="flex"><span class="avatar large">${esc(c.name[0])}</span><div><div class="profile-name">${esc(c.name)}</div><p class="muted">${esc(c.phone)} · ${esc(c.city)}</p></div></div><div class="summary-row total"><span>Outstanding</span><strong>${money(outstanding(id))}</strong></div><h3 class="spaced">Invoice history</h3>${arr.map(i=>`<div class="list-row" style="padding-left:0;padding-right:0"><div><strong>${i.id}</strong><small>${i.date} · ${i.status}</small></div><div>${money(calc(i.items,i.discount).total)}<br><button class="linkbtn" onclick="closeModal();openInvoice('${i.id}')">View invoice</button></div></div>`).join('')||'<p class="muted">No invoices yet. Create a new bill for this customer.</p>'}`,button('Create bill',`closeModal();startNewBill();state.customerId='${id}';render()`,true));}
function payments(){const arr=invoices.filter(i=>i.status==='Finalized'),due=arr.filter(i=>calc(i.items,i.discount).total>i.paid);return heading('Payments & dues','Record customer collections against a finalized invoice.',button('Export collections',"exportCSV('payments')"))+`<div class="metrics"><div class="metric"><div class="cap">Cash collected</div><div class="num">${money(arr.reduce((a,i)=>a+collectionByMethod(i,'Cash'),0))}</div><div class="foot">All demo invoices</div></div><div class="metric"><div class="cap">UPI collected</div><div class="num">${money(arr.reduce((a,i)=>a+collectionByMethod(i,'UPI'),0))}</div><div class="foot">All demo invoices</div></div><div class="metric"><div class="cap">Card / bank collected</div><div class="num">${money(arr.reduce((a,i)=>a+collectionByMethod(i,'Card')+collectionByMethod(i,'Bank'),0))}</div><div class="foot">All demo invoices</div></div><div class="metric"><div class="cap">Customer outstanding</div><div class="num">${money(arr.reduce((a,i)=>a+calc(i.items,i.discount).total-i.paid,0))}</div><div class="foot">${due.length} invoices awaiting payment</div></div></div><div class="panel"><div class="panel-head"><h2>Outstanding invoices</h2><span class="tag amber">${due.length} pending</span></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Invoice</th><th class="numcell">Bill amount</th><th class="numcell">Received</th><th class="numcell">Due</th><th></th></tr></thead><tbody>${due.length?due.map(i=>`<tr><td>${esc(customer(i.customerId).name)}<small>${esc(customer(i.customerId).phone)}</small></td><td>${i.id}</td><td class="numcell">${money(calc(i.items,i.discount).total)}</td><td class="numcell">${money(i.paid)}</td><td class="numcell" style="color:var(--red)">${money(calc(i.items,i.discount).total-i.paid)}</td><td><button class="btn small" onclick="receiptModal('${i.id}')">Collect payment</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">All finalized invoices are fully paid.</td></tr>'}</tbody></table></div></div><div class="panel spaced"><div class="panel-head"><h2>Payment register</h2><span class="muted" style="font-size:12px">Invoice-linked collections</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Method</th><th class="numcell">Collected</th><th>Status</th></tr></thead><tbody>${arr.map(i=>`<tr><td><button class="linkbtn" onclick="openInvoice('${i.id}')">${i.id}</button></td><td>${esc(customer(i.customerId).name)}</td><td>${i.method}</td><td class="numcell">${money(i.paid)}</td><td><span class="tag ${calc(i.items,i.discount).total>i.paid?'amber':''}">${calc(i.items,i.discount).total>i.paid?'Partial':'Paid'}</span></td></tr>`).join('')}</tbody></table></div></div>`;}
function receiptModal(id){const i=invoices.find(x=>x.id===id),due=calc(i.items,i.discount).total-i.paid;modal('Collect customer payment',`<p><strong>${esc(customer(i.customerId).name)}</strong><br><span class="muted">${id}</span></p><div class="summary-row total"><span>Outstanding</span><strong>${money(due)}</strong></div><div class="form-grid spaced"><div class="field"><label for="receipt-amount">Amount received (₹)</label><input id="receipt-amount" type="number" min="0.01" max="${due}" value="${due}"></div><div class="field"><label for="receipt-method">Payment method</label><select id="receipt-method">${['Cash','UPI','Card','Bank'].map(m=>`<option>${m}</option>`).join('')}</select></div></div><div id="form-error" class="error spaced"></div><p class="inline-note">Demo entry only. No payment gateway or bank connection.</p>`,button('Cancel','closeModal()')+button('Record receipt',`collectReceipt('${id}')`,true));}
function collectReceipt(id){let i=invoices.find(x=>x.id===id),due=round(calc(i.items,i.discount).total-i.paid),amount=Number(document.querySelector('#receipt-amount').value),method=document.querySelector('#receipt-method').value;if(!Number.isFinite(amount)||amount<=0||amount>due)return error('Enter a positive amount up to the outstanding balance.');i.originalMethod=i.originalMethod||i.method;i.paid=round(i.paid+amount);if(i.method!==method)i.method='Mixed';i.receipts=i.receipts||[];i.receipts.push({amount,method});events.unshift({time:'Now',action:'Payment received: '+id,detail:method+' · '+money(amount)});closeModal();render();toast('Receipt recorded. Customer due updated.');}
function reports(){const arr=invoices.filter(i=>i.status==='Finalized'),total=arr.reduce((a,i)=>a+calc(i.items,i.discount).total,0),tax=arr.reduce((a,i)=>a+calc(i.items,i.discount).cgst*2,0);return heading('Reports','Sales, stock and collections from your current demo records.',button('Download sales CSV',"exportCSV('sales')"))+`<div class="statline"><div><small>Total finalized sales</small><strong>${money(total)}</strong></div><div><small>GST collected</small><strong>${money(tax)}</strong></div><div><small>Average bill</small><strong>${money(arr.length?total/arr.length:0)}</strong></div><div><small>Finalized invoices</small><strong>${arr.length}</strong></div></div><div class="grid-two"><div class="panel"><div class="panel-head"><h2>Daily sales summary</h2><span class="muted" style="font-size:12px">Demo date range</span></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Invoices</th><th class="numcell">Sales</th><th class="numcell">Collected</th></tr></thead><tbody>${['2026-10-04','2026-10-03'].map(d=>{let a=arr.filter(i=>i.date===d);return `<tr><td>${d}</td><td>${a.length}</td><td class="numcell">${money(a.reduce((s,i)=>s+calc(i.items,i.discount).total,0))}</td><td class="numcell">${money(a.reduce((s,i)=>s+i.paid,0))}</td></tr>`}).join('')}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Report downloads</h2></div>${[['Sales register','sales'],['Stock summary','stock'],['Collection register','payments'],['GST summary','gst']].map(([t,k])=>`<div class="list-row"><div><strong>${t}</strong><small>Current demo records · CSV format</small></div><button class="btn small" onclick="exportCSV('${k}')">Export</button></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2>GST summary</h2><span class="tag blue">Illustrative treatment</span></div><div class="table-wrap"><table><thead><tr><th>Period</th><th class="numcell">Taxable value</th><th class="numcell">CGST</th><th class="numcell">SGST</th><th class="numcell">Total tax</th></tr></thead><tbody><tr><td>All finalized demo invoices</td><td class="numcell">${money(arr.reduce((a,i)=>a+calc(i.items,i.discount).taxable,0))}</td><td class="numcell">${money(tax/2)}</td><td class="numcell">${money(tax/2)}</td><td class="numcell">${money(tax)}</td></tr></tbody></table></div></div><div class="notice">GST reports are a calculation preview, not a statutory filing. Final rules and export requirements need accountant approval.</div>`;}
function exportCSV(type){const arr=invoices.filter(i=>i.status==='Finalized');let rows=type==='stock'?[['Tag','Item','Metal','Purity','Net weight per unit (g)','Available units','Rate per g'],...products.map(p=>[p.tag,p.name,p.metal,p.purity,p.weight,p.qty,p.rate])]:type==='payments'?[['Invoice','Customer','Payment method','Collected','Due'],...arr.map(i=>[i.id,customer(i.customerId).name,i.method,i.paid,calc(i.items,i.discount).total-i.paid])]:type==='gst'?[['Invoice','Taxable value','CGST','SGST','Total'],...arr.map(i=>{const n=calc(i.items,i.discount);return [i.id,n.taxable,n.cgst,n.sgst,n.total]})]:[['Invoice','Date','Customer','Items','Discount %','Total','Collected','Due'],...arr.map(i=>[i.id,i.date,customer(i.customerId).name,i.items.map(x=>x.name).join(' / '),i.discount,calc(i.items,i.discount).total,i.paid,calc(i.items,i.discount).total-i.paid])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('aurum-demo-'+type+'.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('Demo '+type+' report downloaded.');}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function settings(){const tabs=[['profile','Business profile'],['rates','Metal rates'],['print','Invoice & printing'],['users','Users & permissions'],['backup','Backup & restore'],['audit','Activity history']];return heading('Shop settings','Business details, printing preferences and operational controls.')+`<div class="settings-layout"><div class="settings-menu">${tabs.map(([k,t])=>`<button class="${state.settingsTab===k?'active':''}" onclick="state.settingsTab='${k}';render()">${t}</button>`).join('')}</div><div class="panel"><div class="panel-head"><h2>${tabs.find(t=>t[0]===state.settingsTab)?.[1]}</h2><span class="tag blue">Demo owner</span></div><div class="panel-body">${settingsContent()}</div></div></div>`;}
function settingsContent(){if(state.settingsTab==='profile')return `<div class="form-grid"><div class="field"><label for="shopname">Shop name</label><input id="shopname" value="${esc(shop.name)}"></div><div class="field"><label for="shopphone">Phone</label><input id="shopphone" value="${esc(shop.phone)}"></div><div class="field full"><label for="shopaddress">Address</label><input id="shopaddress" value="${esc(shop.address)}"></div><div class="field"><label for="shopgst">GSTIN</label><input id="shopgst" value="${esc(shop.gstin)}"><span class="hint">Demo only. Confirm registration details before launch.</span></div><div class="field"><label>State</label><input value="Uttar Pradesh (09)" readonly></div></div><div class="spaced">${button('Save profile','saveShopProfile()',true)}</div><div class="notice blue">Business details apply to new invoices. Existing invoice snapshots keep their original details.</div>`;
if(state.settingsTab==='rates')return `<p class="muted" style="margin-bottom:20px">Rates are illustrative and apply by item purity. New bills use the current master rates.</p><div class="form-grid"><div class="field"><label for="rate22">22K gold / g (₹)</label><input id="rate22" type="number" min="0.01" value="${products.find(p=>p.purity.startsWith('22K')).rate}"></div><div class="field"><label for="rate18">18K gold / g (₹)</label><input id="rate18" type="number" min="0.01" value="${products.find(p=>p.purity.startsWith('18K')).rate}"></div><div class="field"><label for="ratesilver">Silver / g (₹)</label><input id="ratesilver" type="number" min="0.01" value="${products.find(p=>p.metal==='Silver').rate}"></div></div><div class="spaced">${button('Update master rates','saveRates()',true)}</div><div class="notice">Review rate basis with the client. Updating masters does not recalculate existing invoices or a bill already in progress.</div>`;
if(state.settingsTab==='print')return `<div class="form-grid"><div class="field"><label>Invoice paper</label><input value="A4 portrait" readonly></div><div class="field"><label>Invoice language</label><input value="English · demo" readonly></div><div class="field full"><label for="shopbank">Bank details</label><input id="shopbank" value="${esc(shop.bank)}"></div><div class="field full"><label for="shopterms">Terms & conditions</label><textarea id="shopterms" rows="3">${esc(shop.terms)}</textarea></div></div><div class="spaced flex wrap">${button('Save invoice preferences','savePrintPrefs()',true)}${button('Test print',`printInvoice('${invoices[0].id}')`,false,'print')}</div><p class="inline-note">The browser print dialog lets you select an installed printer or save a PDF. Disable browser headers / footers for a clean invoice.</p><div class="notice blue">Thermal templates, logo and printer-specific integration can be approved after the A4 sample.</div>`;
if(state.settingsTab==='users')return `<p class="muted" style="margin-bottom:17px">Proposed access model. Permissions shown below are illustrative.</p><div class="table-wrap"><table><thead><tr><th>User / role</th><th>Billing</th><th>Stock</th><th>Settings</th></tr></thead><tbody><tr><td>Mimmo Patel · Owner</td><td>Create / cancel</td><td>Manage</td><td>Full access</td></tr><tr><td>Demo cashier</td><td>Create / reprint</td><td>View only</td><td>No access</td></tr><tr><td>Demo accountant</td><td>View</td><td>View</td><td>Reports only</td></tr></tbody></table></div><div class="notice">This prototype runs in a demo owner role. Production login, passwords and permission enforcement require the backend.</div>`;
if(state.settingsTab==='backup')return `<div class="security">${icon('lock')}Keep a second copy away from the shop PC</div><div class="summary-row spaced"><span>Demo backup scope</span><strong>Current browser session</strong></div><div class="summary-row"><span>Format</span><strong>JSON demo data</strong></div><div class="summary-row"><span>Production plan</span><strong>Scheduled SQL backup + restore drill</strong></div><div class="spaced flex wrap">${button('Download demo backup','backupDemo()',true)}<label class="btn" for="restorefile">Restore demo data</label><input id="restorefile" type="file" accept=".json,application/json" style="display:none" onchange="restoreDemo(this.files[0])"></div><div class="notice">Demo backup is a JSON file, not a database backup. Automatic scheduled backup, encryption and restore verification belong to production implementation.</div><button class="btn danger" onclick="resetModal()">Reset demo session</button>`;
return events.map(e=>`<div class="audit-event"><div class="time">${esc(e.time)}</div><div><strong>${esc(e.action)}</strong><small>${esc(e.detail)}</small></div></div>`).join('');}
function saveShopProfile(){let name=document.querySelector('#shopname').value.trim(),address=document.querySelector('#shopaddress').value.trim();if(!name||!address)return toast('Shop name and address are required.');shop.name=name;shop.address=address;shop.phone=document.querySelector('#shopphone').value.trim();shop.gstin=document.querySelector('#shopgst').value.trim();events.unshift({time:'Now',action:'Business profile updated',detail:'Demo owner · Applies to new invoices'});render();toast('Profile saved for this demo session.');}
function savePrintPrefs(){shop.bank=document.querySelector('#shopbank').value.trim();shop.terms=document.querySelector('#shopterms').value.trim();toast('Invoice preferences saved for new invoices.');}
function saveRates(){const a=Number(document.querySelector('#rate22').value),b=Number(document.querySelector('#rate18').value),c=Number(document.querySelector('#ratesilver').value);if([a,b,c].some(n=>!Number.isFinite(n)||n<=0))return toast('All rates must be positive numbers.');products.forEach(p=>p.rate=p.metal==='Silver'?c:p.purity.startsWith('22K')?a:b);events.unshift({time:'Now',action:'Master metal rates updated',detail:'Existing invoices preserved'});render();toast('Rates updated. New bills will use these rates.');}
function backupDemo(){download('aurum-demo-backup.json',JSON.stringify({version:1,customers,products,invoices,shop,events,nextInvoiceNumber},null,2),'application/json');toast('Demo backup downloaded.');}
async function restoreDemo(file){if(!file)return;try{if(file.size>2000000)throw Error('File too large');let d=JSON.parse(await file.text());if(d.customers?.some(c=>!/^c[0-9]+$/.test(c.id))||d.products?.some(p=>!/^p[0-9]+$/.test(p.id))||d.invoices?.some(i=>!/^[-A-Za-z0-9]+$/.test(i.id)||!/^c[0-9]+$/.test(i.customerId)))throw Error('Invalid IDs');if(d.version!==1||!Array.isArray(d.customers)||!d.customers.length||!Array.isArray(d.products)||!d.products.length||!Array.isArray(d.invoices)||!d.shop||!Array.isArray(d.events)||!Number.isInteger(d.nextInvoiceNumber))throw Error('Unsupported backup');if(!d.customers.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.phone==='string')||!d.products.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&Number.isFinite(p.qty)&&p.qty>=0&&Number.isFinite(p.weight)&&Number.isFinite(p.rate)&&Number.isFinite(p.making))||!d.invoices.every(i=>typeof i.id==='string'&&Array.isArray(i.items)&&i.items.every(x=>Number.isFinite(x.weight)&&Number.isFinite(x.rate)&&Number.isFinite(x.qty)&&Number.isFinite(x.making))&&Number.isFinite(i.discount)&&Number.isFinite(i.paid)))throw Error('Invalid demo data');pendingRestore=d;modal('Restore demo backup',`<p>This will replace the current demo records with <strong>${d.invoices.length} invoices</strong>, <strong>${d.customers.length} customers</strong> and <strong>${d.products.length} stock tags</strong>.</p><p class="inline-note">Current unsaved demo changes will be replaced.</p>`,button('Cancel','closeModal()')+button('Restore demo session','confirmRestore()',true));}catch(e){toast('Invalid demo backup. Choose a JSON file downloaded from this demo.');}}
let pendingRestore=null;
function confirmRestore(){if(!pendingRestore)return;({customers,products,invoices,shop,events,nextInvoiceNumber}=pendingRestore);pendingRestore=null;state.cart=[];state.editingInvoice=null;state.customerId=customers[0].id;closeModal();render();toast('Demo backup restored.');}
function resetModal(){modal('Reset demo session',`<p>Reset all bills, customers and stock changes to the original sample data?</p><p class="inline-note">Download a demo backup first if you want to keep your changes.</p>`,button('Keep changes','closeModal()')+button('Reset demo','location.reload()',true));}
function guide(){return heading('Demo walkthrough','A complete shop journey, from opening the counter to reviewing the day.')+`<div class="panel"><div class="panel-head"><h2>Client walkthrough</h2><span class="tag blue">Try each step</span></div>${[['01','Review the shop overview','Check daily sales, customer dues and Cash / UPI collections.','dashboard','Open overview'],['02','Create a jewellery bill','Choose a customer, add gold or silver items, then review weight, rate and making charges.','billing','Create a bill'],['03','Finalize and print','Enter received payment, confirm the bill, then open the A4 print / PDF preview.','invoices','View invoices'],['04','Check inventory changes','The sold tag quantity reduces when you finalize. A cancelled demo invoice restores it.','inventory','Open inventory'],['05','Collect an outstanding balance','Record a payment against a partial invoice and check the customer ledger.','payments','Open dues'],['06','Review sales and tax summaries','Download sales, stock, collection and GST sample reports as CSV.','reports','Open reports'],['07','Configure the shop and protect data','Update shop details, try a print and download / restore a demo backup.','settings','Open settings']].map(([n,t,d,k,b])=>`<div class="guide-step"><span class="n">${n}</span><div><h3 style="margin:0">${t}</h3><p>${d}</p></div><button class="btn small" onclick="go('${k}')">${b}</button></div>`).join('')}</div><div class="notice blue">Demo changes live in this browser session and reset on reload. Production will store transactions in the shop database. This preview does not connect to printers, banks, GST portals or customer notifications automatically.</div>`;}
if(document.modelContext?.registerTool){for(const [name,page] of [['open_billing_workspace','billing'],['open_inventory_workspace','inventory'],['open_demo_walkthrough','guide']]){try{Promise.resolve(document.modelContext.registerTool({name,description:'Open the '+page+' page in this jewellery shop prototype. Does not create a transaction.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');go(page);return {page,transactionCreated:false};}})).catch(()=>{});}catch{}}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();


function collectionByMethod(i,m){const r=i.receipts||[];return round(((i.originalMethod||i.method)===m?i.paid-r.reduce((a,x)=>a+x.amount,0):0)+r.filter(x=>x.method===m).reduce((a,x)=>a+x.amount,0));}




